    // --- STATE VARIABLES ---
    private bool isLoading = false;
    private bool isSaving = false;
    private bool showModal = false;
    private bool showConfirmModal = false;
    private bool isEditing = false;

    private int selectedNamHocInt = DateTime.Now.Year;
    private int selectedHocKy = 1;

    private List<M_QLThoiGianNhapDiemDTO> dotNhapList = new();
    private M_QLThoiGianNhapDiemDTO currentItem = new();
    private M_QLThoiGianNhapDiemDTO? confirmItem;
    private string confirmAction = "";
    private string confirmItemName = "";

    private Dictionary<string, string> validationErrors = new();

    private string startDateStr = "";
    private string startTimeStr = "08:00";
    private string endDateStr = "";
    private string endTimeStr = "17:00";


    private string? maTruongBo;
    private string? selectedCapHoc;
    private string? selectedNamHoc = "2025-2026";
    private string GetDisplayYear(int year) => $"{year}-{year + 1}";
    // --- COMPUTED PROPERTIES ---
    private int activeCount => dotNhapList.Count(x => x.TrangThai == 1 &&
                                                     x.ThoiGianBatDau <= DateTime.Now &&
                                                     x.ThoiGianKetThuc >= DateTime.Now);

    private int inactiveCount => dotNhapList.Count(x => x.TrangThai == 0);

    private int upcomingCount => dotNhapList.Count(x => x.ThoiGianBatDau > DateTime.Now);

    private int completedCount => dotNhapList.Count(x => x.ThoiGianKetThuc < DateTime.Now);

    // --- LIFECYCLE METHODS ---
    protected override async Task OnInitializedAsync()
    {
        maTruongBo = await BrowserStorageService.GetMaTruongBoAsync(JS);
        selectedNamHoc = await BrowserStorageService.GetItem(JS, "selectedNamHoc") ?? "2025-2026";
        selectedCapHoc = await BrowserStorageService.GetItem(JS, "selectedLevel") ?? "02";

        // Parse năm học từ chuỗi "YYYY-YYYY"
        if (!string.IsNullOrEmpty(selectedNamHoc))
        {
            var parts = selectedNamHoc.Split('-');
            if (parts.Length >= 1 && int.TryParse(parts[0].Trim(), out var parsedYear))
                selectedNamHocInt = parsedYear;
        }

        // Đọc học kỳ từ session (lưu bởi TopNavbar)
        var hocKyStr = await BrowserStorageService.GetItem(JS, "selectedHocKy");
        if (!string.IsNullOrEmpty(hocKyStr) && int.TryParse(hocKyStr, out var savedHocKy))
            selectedHocKy = savedHocKy;
        else
            selectedHocKy = DateTime.Now.Month >= 8 && DateTime.Now.Month <= 12 ? 1 : 2;

        if (string.IsNullOrEmpty(maTruongBo))
        {
            await JS.InvokeVoidAsync("alert", "Không tìm thấy mã trường. Vui lòng đăng nhập lại.");
            Nav.NavigateTo("/");
            return;
        }

        await LoadData();
    }

    private bool _toastRegistered = false;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender && !_toastRegistered)
        {
            _toastRegistered = true;
            await JS.InvokeVoidAsync("eval", @"
                if (!window.showToast) {
                    window.showToast = function(message, type) {
                        type = type || 'info';
                        var container = document.getElementById('toast-container');
                        if (!container) {
                            container = document.createElement('div');
                            container.id = 'toast-container';
                            container.style.cssText = 'position:fixed;top:20px;right:20px;z-index:9999;display:flex;flex-direction:column;gap:10px;max-width:350px;';
                            document.body.appendChild(container);
                        }
                        var colors = { success:'#28a745', error:'#dc3545', warning:'#ffc107', info:'#17a2b8' };
                        var toast = document.createElement('div');
                        toast.style.cssText = 'padding:12px 16px;border-radius:6px;color:white;font-family:Segoe UI,sans-serif;font-size:14px;box-shadow:0 4px 12px rgba(0,0,0,.15);display:flex;align-items:center;gap:10px;cursor:pointer;';
                        toast.style.backgroundColor = colors[type] || colors.info;
                        toast.innerText = message;
                        container.appendChild(toast);
                        setTimeout(function(){ if(toast.parentNode) toast.remove(); }, 3000);
                    };
                }
            ");
        }
    }

    private async Task LoadData()
    {
        isLoading = true;
        StateHasChanged();

        try
        {
            // Gọi API lấy danh sách đợt nhập điểm
            dotNhapList = await DiemService.hGetThoiGianNhapDiem(
                selectedNamHocInt,
                selectedHocKy,
                selectedCapHoc,
                maTruongBo
            );
        }
        catch (Exception ex)
        {
            await ShowError($"Lỗi tải dữ liệu: {ex.Message}");
        }
        finally
        {
            isLoading = false;
            StateHasChanged();
        }
    }

    // --- EVENT HANDLERS ---
    private void OnToggleStatusChanged(ChangeEventArgs e)
    {
        if (e.Value is bool isChecked)
        {
            currentItem.TrangThai = isChecked ? 1 : 0;
        }
    }

    // --- MODAL METHODS ---
    private void OpenModal(M_QLThoiGianNhapDiemDTO? item = null)
    {
        isEditing = item != null;

        if (isEditing && item != null)
        {
            // Clone item để chỉnh sửa
            currentItem = new M_QLThoiGianNhapDiemDTO
                {
                    Id = item.Id,
                    TenDotNhap = item.TenDotNhap,
                    HocKy = item.HocKy,
                    NamHoc = item.NamHoc,
                    ThoiGianBatDau = item.ThoiGianBatDau,
                    ThoiGianKetThuc = item.ThoiGianKetThuc,
                    TrangThai = item.TrangThai,
                    Cap = selectedCapHoc,
                    MaTruongBo = maTruongBo
                };
        }
        else
        {
            // Tạo mới
            currentItem = new M_QLThoiGianNhapDiemDTO
                {
                    Id = null,
                    TenDotNhap = "",
                    HocKy = selectedHocKy,
                    NamHoc = selectedNamHocInt,
                    ThoiGianBatDau = DateTime.Now.AddDays(1).Date.AddHours(8), // Ngày mai 8:00
                    ThoiGianKetThuc = DateTime.Now.AddDays(8).Date.AddHours(17), // 7 ngày sau 17:00
                    TrangThai = 1,
                    Cap = selectedCapHoc,
                    MaTruongBo = maTruongBo
                };
        }

        // Chuyển đổi datetime sang string cho input
        UpdateDateTimeStrings();

        validationErrors.Clear();
        showModal = true;
        StateHasChanged();
    }

    private void CloseModal()
    {
        showModal = false;
        currentItem = new M_QLThoiGianNhapDiemDTO();
        validationErrors.Clear();
        StateHasChanged();
    }

    private void UpdateDateTimeStrings()
    {
        startDateStr = currentItem.ThoiGianBatDau.ToString("yyyy-MM-dd");
        startTimeStr = currentItem.ThoiGianBatDau.ToString("HH:mm");
        endDateStr = currentItem.ThoiGianKetThuc.ToString("yyyy-MM-dd");
        endTimeStr = currentItem.ThoiGianKetThuc.ToString("HH:mm");
    }

    private void OnStartDateChanged(ChangeEventArgs e)
    {
        var dateStr = e.Value?.ToString();
        if (!string.IsNullOrEmpty(dateStr))
        {
            startDateStr = dateStr;
            UpdateStartDateTime();
        }
    }

    private void OnStartTimeChanged(ChangeEventArgs e)
    {
        var timeStr = e.Value?.ToString();
        if (!string.IsNullOrEmpty(timeStr))
        {
            startTimeStr = timeStr;
            UpdateStartDateTime();
        }
    }

    private void OnEndDateChanged(ChangeEventArgs e)
    {
        var dateStr = e.Value?.ToString();
        if (!string.IsNullOrEmpty(dateStr))
        {
            endDateStr = dateStr;
            UpdateEndDateTime();
        }
    }

    private void OnEndTimeChanged(ChangeEventArgs e)
    {
        var timeStr = e.Value?.ToString();
        if (!string.IsNullOrEmpty(timeStr))
        {
            endTimeStr = timeStr;
            UpdateEndDateTime();
        }
    }

    private void UpdateStartDateTime()
    {
        if (DateTime.TryParse($"{startDateStr} {startTimeStr}", out var newDateTime))
        {
            currentItem.ThoiGianBatDau = newDateTime;
        }
        else if (DateTime.TryParse(startDateStr, out var dateOnly))
        {
            if (TimeSpan.TryParse(startTimeStr, out var timeOnly))
            {
                currentItem.ThoiGianBatDau = dateOnly.Add(timeOnly);
            }
            else
            {
                currentItem.ThoiGianBatDau = dateOnly;
            }
        }
    }

    private void UpdateEndDateTime()
    {
        if (DateTime.TryParse($"{endDateStr} {endTimeStr}", out var newDateTime))
        {
            currentItem.ThoiGianKetThuc = newDateTime;
        }
        else if (DateTime.TryParse(endDateStr, out var dateOnly))
        {
            if (TimeSpan.TryParse(endTimeStr, out var timeOnly))
            {
                currentItem.ThoiGianKetThuc = dateOnly.Add(timeOnly);
            }
            else
            {
                currentItem.ThoiGianKetThuc = dateOnly;
            }
        }
    }

    // --- VALIDATION ---
    private bool ValidateForm()
    {
        validationErrors.Clear();
        bool isValid = true;

        // Validate tên đợt nhập
        if (string.IsNullOrWhiteSpace(currentItem.TenDotNhap))
        {
            validationErrors["TenDotNhap"] = "Vui lòng nhập tên đợt nhập điểm";
            isValid = false;
        }
        else if (currentItem.TenDotNhap.Length > 200)
        {
            validationErrors["TenDotNhap"] = "Tên đợt nhập không được vượt quá 200 ký tự";
            isValid = false;
        }

        // Validate thời gian
        if (currentItem.ThoiGianBatDau >= currentItem.ThoiGianKetThuc)
        {
            validationErrors["ThoiGianKetThuc"] = "Thời gian kết thúc phải sau thời gian bắt đầu";
            isValid = false;
        }

        // Validate không trùng lặp thời gian với các đợt khác
        var overlappingPeriods = dotNhapList
            .Where(x => x.Id != currentItem.Id &&
                        ((currentItem.ThoiGianBatDau >= x.ThoiGianBatDau && currentItem.ThoiGianBatDau <= x.ThoiGianKetThuc) ||
                         (currentItem.ThoiGianKetThuc >= x.ThoiGianBatDau && currentItem.ThoiGianKetThuc <= x.ThoiGianKetThuc) ||
                         (currentItem.ThoiGianBatDau <= x.ThoiGianBatDau && currentItem.ThoiGianKetThuc >= x.ThoiGianKetThuc)))
            .ToList();

        if (overlappingPeriods.Any())
        {
            validationErrors["ThoiGianBatDau"] = "Thời gian đợt nhập bị trùng với đợt khác";
            isValid = false;
        }

        return isValid;
    }

    // --- CRUD OPERATIONS ---
    private async Task SavePeriod()
    {
        if (!ValidateForm())
        {
            StateHasChanged();
            return;
        }

        isSaving = true;
        StateHasChanged();

        try
        {
            // Gọi API lưu dữ liệu
            await DiemService.hUpsertThoiGianNhapDiem(currentItem);

            // Đóng modal và reload dữ liệu
            CloseModal();
            await LoadData();

            await ShowSuccess(
                isEditing ? "Cập nhật đợt nhập điểm thành công!" : "Tạo đợt nhập điểm mới thành công!"
            );
        }
        catch (Exception ex)
        {
            await ShowError($"Lỗi khi lưu đợt nhập: {ex.Message}");
        }
        finally
        {
            isSaving = false;
            StateHasChanged();
        }
    }

    private void ToggleStatus(M_QLThoiGianNhapDiemDTO item)
    {
        confirmItem = item;
        confirmItemName = item.TenDotNhap;
        confirmAction = item.TrangThai == 1 ? "lock" : "unlock";
        showConfirmModal = true;
        StateHasChanged();
    }

    private void CloseConfirmModal()
    {
        showConfirmModal = false;
        confirmItem = null;
        confirmItemName = "";
        confirmAction = "";
        StateHasChanged();
    }

    private async Task ConfirmToggleStatus()
    {
        if (confirmItem != null)
        {
            try
            {
                // Toggle trạng thái
                confirmItem.TrangThai = confirmItem.TrangThai == 1 ? 0 : 1;

                // Gọi API lưu thay đổi
                await DiemService.hUpsertThoiGianNhapDiem(confirmItem);

                // Reload dữ liệu
                await LoadData();
                CloseConfirmModal();

                await ShowSuccess(
                    $"Đã {(confirmAction == "lock" ? "khóa" : "mở")} đợt nhập điểm thành công!"
                );
            }
            catch (Exception ex)
            {
                await ShowError($"Lỗi khi thay đổi trạng thái: {ex.Message}");
            }
        }
    }

    private async Task ClonePeriod(M_QLThoiGianNhapDiemDTO item)
    {
        try
        {
            // Tạo bản sao với tên mới
            var clone = new M_QLThoiGianNhapDiemDTO
                {
                    Id = null,
                    TenDotNhap = $"{item.TenDotNhap} (Bản sao)",
                    HocKy = item.HocKy,
                    NamHoc = item.NamHoc + 1, // Mặc định sang năm sau
                    ThoiGianBatDau = item.ThoiGianBatDau.AddYears(1),
                    ThoiGianKetThuc = item.ThoiGianKetThuc.AddYears(1),
                    TrangThai = 0 // Mặc định là đã tắt
                };

            // Mở modal để chỉnh sửa
            currentItem = clone;
            UpdateDateTimeStrings();
            isEditing = false;
            validationErrors.Clear();
            showModal = true;
            StateHasChanged();

            await ShowInfo("Đã tạo bản sao đợt nhập. Vui lòng kiểm tra và lưu lại.");
        }
        catch (Exception ex)
        {
            await ShowError($"Lỗi khi sao chép: {ex.Message}");
        }
    }

    // --- HELPER METHODS ---
    private async Task ShowSuccess(string message)
    {
        try
        {
            await JS.InvokeVoidAsync("showToast", message, "success");
        }
        catch
        {
            await JS.InvokeVoidAsync("alert", $"✅ {message}");
        }
    }

    private async Task ShowError(string message)
    {
        try
        {
            await JS.InvokeVoidAsync("showToast", message, "error");
        }
        catch
        {
            await JS.InvokeVoidAsync("alert", $"❌ {message}");
        }
    }

    private async Task ShowInfo(string message)
    {
        try
        {
            await JS.InvokeVoidAsync("showToast", message, "info");
        }
        catch
        {
            await JS.InvokeVoidAsync("alert", $"ℹ️ {message}");
        }
    }

